export type Fields = { name: string; email: string; message: string };
export type Errors = Partial<Record<keyof Fields, string>>;

export function validate(input: Fields): Errors {
  const errors: Errors = {};
  if (!input.name.trim()) errors.name = 'Name is required.';
  const email = input.email.trim();
  if (!email) errors.email = 'Email is required.';
  else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.email = 'Enter a valid email address.';
  if (input.message.trim().length < 20) errors.message = 'Message must be at least 20 characters.';
  return errors;
}
