---
import { getCollection, render } from 'astro:content';
import Layout from '../../layouts/Layout.astro';

export async function getStaticPaths() {
  const books = await getCollection('books');
  return books.map((book) => ({ params: { slug: book.id }, props: { book } }));
}
const { book } = Astro.props;
const { Content } = await render(book);
const { title, author, year, rating, tags } = book.data;
---
<Layout title={`${title} | Bookshelf`}>
  <h1>{title}</h1>
  <p>by {author}</p>
  <p>Published in {year}</p>
  <p>Rating: {rating}/5</p>
  <ul>
    {tags.map((t) => <li><a href="/books">{t}</a></li>)}
  </ul>
  <div><Content /></div>
  <button type="button" id="fav" data-slug={book.id}>Add to favorites</button>
</Layout>
<script>
  import { getFavorites, setFavorites } from '../../lib/favorites';
  const btn = document.querySelector<HTMLButtonElement>('#fav')!;
  const slug = btn.dataset.slug!;
  const paint = () => {
    btn.textContent = getFavorites().includes(slug) ? 'Remove from favorites' : 'Add to favorites';
  };
  paint();
  btn.addEventListener('click', () => {
    const list = getFavorites();
    setFavorites(list.includes(slug) ? list.filter((s) => s !== slug) : [...list, slug]);
    paint();
  });
</script>
