import Layout from '../layouts/Layout.astro';
import { validate, type Errors } from '../lib/validate';
export const prerender = false;

let values = { name: '', email: '', message: '' };
let errors: Errors = {};
let success = '';
if (Astro.request.method === 'POST') {
  const data = await Astro.request.formData();
  const str = (k: string) => String(data.get(k) ?? '');
  values = { name: str('name'), email: str('email'), message: str('message') };
  errors = validate(values);
  if (Object.keys(errors).length === 0) {
    success = `Thanks, ${values.name.trim()}! Your message has been sent.`;
  }
}
---
<Layout title="Contact | Bookshelf">
  <h1>Contact</h1>
  <div id="contact">
    {success && <p id="success">{success}</p>}
    {!success && (
      <form method="post" action="/contact" novalidate id="contact-form">
        <div>
          <label for="name">Name</label>
          <input type="text" id="name" name="name" value={values.name} />
          <span class="error" data-for="name">{errors.name}</span>
        </div>
        <div>
          <label for="email">Email</label>
          <input type="email" id="email" name="email" value={values.email} />
          <span class="error" data-for="email">{errors.email}</span>
        </div>
        <div>
          <label for="message">Message</label>
          <textarea id="message" name="message">{values.message}</textarea>
          <span class="error" data-for="message">{errors.message}</span>
        </div>
        <button type="submit">Send</button>
      </form>
    )}
  </div>
</Layout>
<script>
  import { validate } from '../lib/validate';
  const form = document.querySelector<HTMLFormElement>('#contact-form');
  form?.addEventListener('submit', async (e) => {
    e.preventDefault();
    const data = new FormData(form);
    const str = (k: string) => String(data.get(k) ?? '');
    const errors = validate({ name: str('name'), email: str('email'), message: str('message') });
    for (const span of form.querySelectorAll<HTMLElement>('.error')) {
      span.textContent = errors[span.dataset.for as keyof typeof errors] ?? '';
    }
    if (Object.keys(errors).length > 0) return;
    const res = await fetch('/contact', { method: 'POST', body: new URLSearchParams(data as any) });
    const doc = new DOMParser().parseFromString(await res.text(), 'text/html');
    const next = doc.querySelector('#contact');
    if (next) document.querySelector('#contact')!.innerHTML = next.innerHTML;
  });
</script>
